#!/bin/sh
# Generates the Homebrew 7 Cask definition for GDocker.
# Usage: scripts/generate-cask.sh <version> <sha256> [output_path]
set -eu

raw_version="${1:?usage: scripts/generate-cask.sh <version> <sha256> [output_path]}"
sha="${2:?usage: scripts/generate-cask.sh <version> <sha256> [output_path]}"
output="${3:-}"

version="${raw_version#v}"

render_cask() {
    cat <<EOF
# This file was generated by GDocker release automation. DO NOT EDIT.
cask "gdocker" do
  version "$version"
  sha256 "$sha"

  url "https://github.com/Diaszano/gdocker/releases/download/v#{version}/GDocker-#{version}.zip"
  name "GDocker"
  desc "Native macOS Docker GUI with a built-in MCP server for AI clients"
  homepage "https://github.com/Diaszano/gdocker"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on macos: :sonoma

  app "GDocker.app"

  # The app is ad-hoc signed, not notarized, so Gatekeeper would refuse to open it with the quarantine flag set.
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/GDocker.app"]
  end

  zap trash: [
    "~/Library/Application Support/GDocker",
    "~/Library/Preferences/com.diaszano.gdocker.plist",
  ]
end
EOF
}

if [ -n "$output" ]; then
    mkdir -p "$(dirname "$output")"
    render_cask > "$output"
else
    render_cask
fi
